                    bgs.append(sc.get('val'))
        for sp in slide._element.spTree.findall(qn('p:sp')):
            txts = sp.findall('.//' + qn('a:r'))
            if not txts:
                continue
            # fill under this shape's text
            spPr = sp.find(qn('p:spPr'))
            fill_el = spPr.find(qn('a:solidFill'))
            local = fill_el.find(qn('a:srgbClr')).get('val') if fill_el is not None else None
            cands = ([local] if local else []) + bgs
            for run in txts:
                col = run.find(qn('a:rPr') + '/' + qn('a:srgbClr'))
                if col is None:
                    continue
                v = col.get('val')
                if all(cr(v, b) < 4.5 for b in cands):
                    bad.append(f's{i}: text #{v} (no bg >=4.5)')
    print(name, '|', 'contrast OK' if not bad else bad[:5])
